def lps(s: str) -> int:
    def longest_palindromic_subsequence(s):
        n = len(s)
        # Create a 2D DP table to store lengths of palindromic subsequences
        dp = [[0] * n for _ in range(n)]

        # Single character palindromes
        for i in range(n):
            dp[i][i] = 1

        # Check subsequences of length 2 and more
        for cl in range(2, n + 1):
            for i in range(n - cl + 1):
                j = i + cl - 1
                if s[i] == s[j]:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        return dp[0][n - 1]

    # Remove non-alphanumeric characters and make the string uppercase
    cleaned_str = ''.join(filter(str.isalnum, s)).upper()
    return longest_palindromic_subsequence(cleaned_str)
