def max_Product(nums):
    if len(nums) < 2:
        raise ValueError("Array must contain at least two integers")

    # Initialize maximum and second maximum values
    max1 = max2 = float('-inf')
    # Initialize minimum and second minimum values
    min1 = min2 = float('inf')

    for num in nums:
        # Update maximum and second maximum values
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update minimum and second minimum values
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare the products of the two largest and two smallest numbers
    product1 = max1 * max2
    product2 = min1 * min2

    if product1 >= product2:
        return (max1, max2)
    else:
        return (min1, min2)

# Example usage and tests
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([0, -1, -2, -4, 5, 0, -6]) == (-6, -4)
assert max_Product([10, 20, -30, -40, 50]) == (-40, -30)
assert max_Product([-1, -2]) == (-1, -2)
assert max_Product([0, 1]) == (0, 1)
