def find_Index(n):
    def triangular_number(index):
        return index * (index + 1) // 2

    def num_digits(number):
        return len(str(number))

    index = 1
    while True:
        t_number = triangular_number(index)
        if num_digits(t_number) >= n:
            return index
        index += 1

# Example Test
assert find_Index(2) == 4
```

